// Rodada 19 (T8, history19) — marcos da história da música 1926–2026 (docs/db19.md §3.10) e geopolítica (§3.11), só dados.
// Cada marco: texto com fatos documentados (fonte curta em `ref`), um efeito mecânico simples (apelo por família/gênero e
// mercado de origem, empurrão de genrePop, caixa dos rivais) e um tipo de decisão `k` (sim/sys/history19.ts monta o cartão,
// as opções e os ecos). Regras: nada que afirme o destino de uma pessoa real (mortes, crimes, prisões só como fato público
// já documentado, sem vítimas nomeadas); nomes de empresas/paradas do jogo seguem a convenção fictícia (WorldSound, ClipNet…).
import { l, type L, type MarketId } from './world';
import type { GeoEvent, GeoEffects, GeoKind, CensorTag } from './content';

/** tipo da decisão: onda/cena, tecnologia, regra/lei, palco/vitrine, crise, negócio */
export type HK19 = 'wave' | 'tech' | 'law' | 'stage' | 'crisis' | 'deal';
export interface H19 {
  id: string; y: number; m?: number; tech?: string; until?: number; w?: true;
  k: HK19; ref: string; t: L; x: L;
  /** famílias ou gêneros favorecidos (apelo e genrePop) */
  g?: string[];
  /** só atos sediados nestes mercados */
  mk?: MarketId[];
  /** multiplicador de apelo enquanto vigora (padrão 1) */
  ap?: number;
  /** só singles (1) ou só álbuns (2) */
  ty?: 1 | 2;
  /** empurrão em genrePop no disparo */
  pop?: number;
  /** caixa dos rivais × riv no disparo */
  riv?: number;
}
const T = (s: string): L => { const [pt, en] = s.split('~'); return l(pt, en ?? pt); };
const H = (id: string, y: number, m: number | undefined, k: HK19, ref: string, t: string, x: string, o: Partial<H19> = {}): H19 =>
  ({ id: 'h19_' + id, y, ...(m === undefined ? {} : { m }), k, ref, t: T(t), x: T(x), ...o });

