const ge = (id: string, name: string, kind: GeoKind, markets: MarketId[], from: number, to: number, effects: GeoEffects, desc: string, cities?: string[]): GeoEvent =>
  ({ id: 'geo19_' + id, name: T(name), kind, markets, from, to, effects, desc: T(desc), ...(cities ? { cities } : {}) });
const fx = (censorshipLevel: number, bannedTags: CensorTag[], demandMult: number, extra: Partial<GeoEffects> = {}): GeoEffects => ({ censorshipLevel, bannedTags, demandMult, ...extra });

